/**
 * plusquam — sign-in page logic
 *
 * Real auth: POST /auth/login → on success, hand a single-use code to the app.
 * Because the sign-in and app are different origins, the app exchanges this
 * short-lived code once for a session token. The JWT never enters a URL.
 * (A cookie scoped to .plusquam.xyz is a future option if cross-tab SSO is needed.)
 */
(function () {
  // Generated by scripts/deploy.sh from the deployed backend stack output.
  const API_BASE = window.PLUSQUAM_CONFIG?.apiBase || '';

  const isLocal = location.hostname === 'localhost' || location.hostname === '127.0.0.1';
  const APP_URL = isLocal
    ? 'http://localhost:5173/'
    : (window.PLUSQUAM_CONFIG?.appUrl || '');

  // Role toggle (cosmetic — the server determines the real role from the DB)
  const roleButtons = document.querySelectorAll('[data-role]');
  roleButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      roleButtons.forEach(b => b.classList.toggle('active', b === btn));
    });
  });

  // Forgot password → no automatic reset; reveal the admin-contact message.
  const forgotLink = document.getElementById('forgot-link');
  const forgotMsg  = document.getElementById('forgot-msg');
  if (forgotLink && forgotMsg) {
    forgotLink.addEventListener('click', (e) => {
      e.preventDefault();
      forgotMsg.hidden = false;
      forgotLink.style.display = 'none';
    });
  }

  const form = document.getElementById('signin-form');
  if (!form) return;
  const btn = form.querySelector('.signin-button');

  // Inline error slot
  let errEl = document.getElementById('signin-error');
  if (!errEl) {
    errEl = document.createElement('p');
    errEl.id = 'signin-error';
    errEl.setAttribute('role', 'alert');
    errEl.classList.add('signin-error-message');
    form.appendChild(errEl);
  }
  const showError = (msg) => { errEl.textContent = msg; errEl.style.display = 'block'; };
  const clearError = () => { errEl.style.display = 'none'; };

  const lang = () => (document.documentElement.lang === 'en' ? 'en' : 'de');
  const T = {
    de: { missing: 'Bitte E-Mail und Passwort eingeben.', invalid: 'Ungültige Anmeldedaten.', network: 'Verbindungsfehler. Bitte erneut versuchen.' },
    en: { missing: 'Please enter your email and password.', invalid: 'Invalid credentials.', network: 'Connection error. Please try again.' },
  };
  const msg = (k) => T[lang()][k];

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    clearError();
    const email    = form.email.value.trim();
    const password = form.password.value;
    if (!email || !password) { showError(msg('missing')); return; }
    if (!API_BASE || !APP_URL) { showError(msg('network')); return; }

    const original = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = '…'; }

    try {
      const res = await fetch(`${API_BASE}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
        referrerPolicy: 'no-referrer',
      });

      if (res.status === 401) {
        showError(msg('invalid'));
        if (btn) { btn.disabled = false; btn.textContent = original; }
        return;
      }
      if (!res.ok) throw new Error(`HTTP ${res.status}`);

      const { handoffCode } = await res.json();
      if (!handoffCode) throw new Error('no login code');

      if (btn) { btn.textContent = '✓'; btn.style.background = 'var(--pq-success)'; }
      window.location.replace(`${APP_URL}#c=${encodeURIComponent(handoffCode)}`);
    } catch (err) {
      console.error('[plusquam] login failed:', err);
      showError(msg('network'));
      if (btn) { btn.disabled = false; btn.textContent = original; }
    }
  });
})();
